import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        const uid = String(decoded._id || decoded.id || decoded.userId || "");
        setCurrentUserId(uid);
      } catch (err) {
        console.error("Token decode failed", err);
      }
    }

    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => setItems(data))
      .catch((err) => console.error("Fetch error", err))
      .finally(() => setLoading(false));
  }, []);

  // Improved filtering
  // === FIXED FILTER - Try this ===
  const filteredItems = React.useMemo(() => {
    if (!currentUserId) {
      return items; // show all until we have user id
    }

    return items.filter((item) => {
      if (!item) return false;

      // === CHANGE THIS LINE based on your actual data ===
      const sellerId = String(item.userId || item.user || item.sellerId || item.seller || item.postedBy || item.owner || "");

      const isNotMine = sellerId !== String(currentUserId);

      const title = (item.title || "").toLowerCase();
      const matchesSearch = searchTerm === "" || title.includes(searchTerm.toLowerCase());

      return isNotMine && matchesSearch;
    });
  }, [items, currentUserId, searchTerm]);

  if (loading) return <h1>Loading...</h1>;

  return (
    <>
      <Navbar />
      <div className="Body">
        {/* Search Bar */}
        <div style={{ padding: "20px", textAlign: "center" }}>
          <div style={{ position: "relative", display: "inline-block", width: "100%", maxWidth: "550px" }}>
            <input
              type="text"
              placeholder="Search for books..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                backgroundColor: "#fbfbfb",
                padding: "16px 40px 16px 20px",
                width: "100%",
                borderRadius: "27px",
                border: "1px solid #ddd",
                outline: "none",
                fontSize: "16px",
              }}
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm("")}
                style={{
                  position: "absolute",
                  right: "15px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  color: "#999",
                  fontSize: "20px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                ×
              </button>
            )}
          </div>
        </div>

        {/* Books Grid */}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px', justifyContent: 'center' }}>
          {filteredItems.length === 0 ? (
            <div className="HeadMo">
              <h1>
                {searchTerm 
                  ? `No books found matching "${searchTerm}"` 
                  : "No books for sale right now!"}
              </h1>
            </div>
          ) : (
            filteredItems.map((item) => {
              const itemId = String(item._id || item.id);
              const isPurchased = !!purchasedItems[itemId];

              return (
                <Card key={itemId} {...item}>
                  <button
                    onClick={() => !isPurchased && onBuy(item)}
                    disabled={isPurchased}
                    style={{
                      backgroundColor: isPurchased ? "#6c757d" : "#0d6efd",
                      color: "#fff",
                      borderRadius: "5px",
                      padding: "10px",
                      width: "140px",
                      border: "none",
                      cursor: isPurchased ? "not-allowed" : "pointer",
                      opacity: isPurchased ? 0.6 : 1,
                    }}
                  >
                    {isPurchased ? "Added to Cart" : "Add to Cart"}
                  </button>
                </Card>
              );
            })
          )}
        </div>
      </div>
      <Footer />
    </>
  );
}

export default Shop;
